const $=s=>document.querySelector(s);
const scenes=[
 {id:'users',title:'The happy path',sub:'200 · Everything clicks',icon:'✓',url:'demo://api/users/1',method:'GET',desc:'Fetch a user profile. Expect a 200 OK response.'},
 {id:'private',title:'Members only',sub:'401 · Who goes there?',icon:'⌑',url:'demo://api/private',method:'GET',desc:'Read a protected profile. Break it to remove authentication.'},
 {id:'projects',title:'Make something',sub:'201 · A new beginning',icon:'+',url:'demo://api/projects',method:'POST',desc:'Create a project with JSON. Break it to send a malformed body.'},
 {id:'slow',title:'The slow burn',sub:'200 · Worth the wait',icon:'◷',url:'demo://api/slow',method:'GET',desc:'A slow response. Break it to trigger a gateway timeout.'},
 {id:'limited',title:'Too much, too fast',sub:'429 · Take a breath',icon:'ϟ',url:'demo://api/limited',method:'GET',desc:'A rate limit response. Check Retry-After to learn when to retry.'},
 {id:'custom',title:'Your own story',sub:'LIVE · Bring an API',icon:'↗',url:'https://jsonplaceholder.typicode.com/users/1',method:'GET',desc:'Send a live request to a public API. Browser CORS rules apply.'}
];
let scene=scenes[0],broken=false,current=null,history=[],tab='body',busy=false,swReady;
$('#scenes').innerHTML=scenes.map((s,i)=>`<button class="scene ${i===0?'active':''}" data-id="${s.id}"><span class="symbol">${String(i+1).padStart(2,'0')}</span><span><b>${s.title}</b><small>${s.sub}</small></span></button>`).join('');
document.querySelectorAll('.scene').forEach(b=>b.onclick=()=>selectScene(b.dataset.id));
function selectScene(id){scene=scenes.find(s=>s.id===id);broken=false;$('#break').setAttribute('aria-pressed','false');$('#url').value=scene.url;$('#method').value=scene.method;$('#headers').value=JSON.stringify(scene.id==='private'?{'Content-Type':'application/json',Authorization:'Bearer cinema-demo'}:{'Content-Type':'application/json'},null,2);$('#body').value=JSON.stringify({name:'My next big idea'},null,2);$('#sceneDescription').textContent=scene.desc;document.querySelectorAll('.scene').forEach(b=>b.classList.toggle('active',b.dataset.id===id));$('#modeBadge').textContent=id==='custom'?'LIVE REQUEST':'LOCAL DEMO API';$('#break').disabled=id==='custom';}
$('#break').onclick=()=>{broken=!broken;$('#break').setAttribute('aria-pressed',String(broken));$('#sceneDescription').textContent=broken?({users:'Plot twist: this user does not exist.',private:'Access token removed. Will the server let you in?',projects:'The JSON body is malformed. Watch the server reject it.',slow:'The upstream server takes too long to answer.',limited:'Already rate limited. Retry-After explains the next step.'}[scene.id]):scene.desc;};
async function setupWorker(){if(!('serviceWorker'in navigator))throw Error('Service workers are unavailable. Use localhost or HTTPS.');await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise((resolve,reject)=>{navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true});setTimeout(()=>reject(Error('Demo API is not ready. Reload and try again.')),6000);});}
swReady=setupWorker();swReady.catch(()=>{});
$('#requestForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('#send').disabled=true;$('#send').textContent='In flight…';document.querySelectorAll('.scene,.challenge-card,#method,#url,#headers,#body,#break').forEach(el=>el.disabled=true);$('#journeyState').textContent='REQUEST LEAVING THE BROWSER';$('#track').className='track sending';const start=performance.now();let waiting;let timeout;let submitted=null;const entered=$('#url').value.trim();let url=entered;const method=$('#method').value;const isDemo=entered.startsWith('demo://');try{let headers=JSON.parse($('#headers').value||'{}');if(!headers||Array.isArray(headers)||typeof headers!=='object')throw Error('Headers must be a JSON object.');let body=$('#body').value;if(isDemo){await swReady;const parsed=new URL(entered);const route=parsed.pathname.slice(1);url=new URL('./__demo/'+(route||'users'),location.href);if(broken){url.searchParams.set('broken','1');if(scene.id==='private')delete headers.Authorization;if(scene.id==='projects')body='{"name":';}}else{const parsed=new URL(url);if(!['http:','https:'].includes(parsed.protocol))throw Error('Use an https:// URL or a demo:// endpoint.');}
 submitted={url:entered,method,headers:new Headers(headers),body};$('#outLabel').textContent=method+' → REQUEST';$('#inLabel').textContent='AWAITING RESPONSE';$('#track .connection:not(.return) .packet').textContent=method;$('#modeBadge').textContent=isDemo?'LOCAL DEMO API':'LIVE REQUEST';$('#transport').textContent=isDemo?'Real fetch · local service worker endpoint':'Real fetch · external API · browser networking';waiting=setTimeout(()=>{$('#track').className='track waiting';$('#journeyState').textContent='WAITING FOR THE RESPONSE';},300);const controller=new AbortController();timeout=setTimeout(()=>controller.abort(),15000);const sent=performance.now();const res=await fetch(url,{method,headers,body:['GET','HEAD'].includes(method)?undefined:body,signal:controller.signal,cache:'no-store'});const firstByte=performance.now();const text=await res.text();const end=performance.now();let data;try{data=JSON.parse(text);}catch{data=text;}current={status:res.status,statusText:res.statusText,ok:res.ok,data,text,headers:Object.fromEntries(res.headers.entries()),ms:Math.round(end-sent),wait:Math.round(firstByte-sent),read:Math.round(end-firstByte),size:new TextEncoder().encode(text).length,url:entered,method,broken,scene:scene.id};clearTimeout(waiting);$('#inLabel').textContent='← '+res.status+' '+(res.statusText||'');$('#track .return .packet').textContent=res.status;$('#serverCaption').textContent=res.ok?'Request accepted':'Request rejected';$('#track').className='track receiving';$('#journeyState').textContent='RESPONSE ARRIVED · '+res.status;await new Promise(r=>setTimeout(r,500));$('#track').className='track'+(res.ok?'':' error');
 }catch(error){clearTimeout(waiting);current={status:0,ok:false,data:{error:error.name==='AbortError'?'request_timeout':'request_failed',message:error.name==='AbortError'?'The request exceeded the 15-second client timeout.':error.message},headers:{},ms:Math.round(performance.now()-start),wait:0,read:0,size:0,url:entered,method,scene:scene.id};current.text=JSON.stringify(current.data,null,2);$('#inLabel').textContent='NO HTTP RESPONSE';$('#track').className='track error';$('#journeyState').textContent='REQUEST COULD NOT COMPLETE';}finally{clearTimeout(timeout);busy=false;document.querySelectorAll('.scene,.challenge-card,#method,#url,#headers,#body,#break').forEach(el=>el.disabled=false);$('#break').disabled=scene.id==='custom';$('#send').disabled=false;$('#send').innerHTML='Send request <span>↗</span>';history.push(current);history=history.slice(-10);updateMetrics();render();window.dispatchEvent(new CustomEvent('cinema:response',{detail:{response:current,request:submitted}}));}};
function updateMetrics(){$('#metrics').replaceChildren();const s=document.createElement('span');s.className='status'+(current.ok?'':' error');s.textContent=current.status?`${current.status} ${current.statusText||''}`:'NETWORK ERROR';$('#metrics').append(s);for(const t of [`${current.ms} ms`,`${(current.size/1024).toFixed(2)} KB`]){const el=document.createElement('span');el.className='muted';el.textContent=t;$('#metrics').append(el);}$('#responseHint').textContent=current.ok?'Request complete. Open “What happened?” to explore why.':'A failed request can teach you a lot. See “What happened?”';}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===b)));render();});
function jsonNode(value,key){if(value!==null&&typeof value==='object'){const d=document.createElement('details');d.className='json';d.open=true;const s=document.createElement('summary');s.textContent=(key!==undefined?key+': ':'')+(Array.isArray(value)?`Array [${value.length}]`:'Object {'+Object.keys(value).length+'}');d.append(s);Object.entries(value).forEach(([k,v])=>d.append(jsonNode(v,k)));return d;}const row=document.createElement('div');row.className='json-value';if(key!==undefined){const k=document.createElement('span');k.className='json-key';k.textContent=key+': ';row.append(k);}const v=document.createElement('span');v.className=value===null?'json-null':typeof value==='number'?'json-number':'json-string';v.textContent=JSON.stringify(value);row.append(v);return row;}
function explain(){if(!current.status)return ['The request never became an HTTP response.','A browser network failure can mean CORS restrictions, an unreachable host, an invalid request, or a connection problem. It is not an HTTP 500. Try the built-in scenes to isolate the issue.'];const map={200:['The server said: all good.','200 OK means the request succeeded. The response body is the data returned by this endpoint. Expand the JSON objects to inspect individual fields.'],201:['A new resource entered the story.','201 Created means the server accepted the data and created a resource. The demo returns a project ID and echoes your submitted fields; it does not persist projects.'],400:['The server could not read the script.','400 Bad Request means the input was invalid. In this scene, malformed JSON or a missing name is rejected. Send valid JSON containing a non-empty name using POST. Turn off Break it if enabled.'],401:['You need an invitation.','401 Unauthorized means valid authentication is missing. Send Authorization: Bearer cinema-demo in the Headers editor. If Break it is enabled, turn it off so your header is sent. The demo checks a fixed sample token; it is not a production authentication system.'],404:['This address leads nowhere.','404 Not Found means the server was reached, but the requested resource was not found. Use demo://api/users/1 and turn off Break it if enabled.'],429:['You are moving faster than the server allows.','429 Too Many Requests indicates a rate limit. The Retry-After header asks you to wait 30 seconds. This demonstration always returns 429; it does not track real quotas.'],504:['The server ran out of waiting time.','504 Gateway Timeout means a gateway did not get an upstream response in time. This demo intentionally returns 504 after a delay. Turn off Break it to try a slow but successful request.']};return map[current.status]||['An HTTP response arrived.',`The server returned status ${current.status}. Inspect the body and headers for the endpoint’s explanation. Browser access controls can hide some headers.`];}
function render(){const c=$('#responseContent');c.replaceChildren();if(!current){c.innerHTML='<div class="empty"><span class="empty-icon" aria-hidden="true">{ ··· }</span><b>No response yet.</b><p>Choose a scene, then send a request to inspect the result.</p></div>';return;}if(tab==='body')c.append(jsonNode(current.data));if(tab==='headers'){const entries=Object.entries(current.headers);if(!entries.length)c.textContent='No response headers available.';entries.forEach(([k,v])=>{const row=document.createElement('div');row.className='header-row';const b=document.createElement('b');b.textContent=k;const span=document.createElement('span');span.textContent=v;row.append(b,span);c.append(row);});}if(tab==='timing'){[['Wait for headers',current.wait],['Read body',current.read],['Total fetch',current.ms]].forEach(([label,ms])=>{const row=document.createElement('div');row.className='timing-row';const name=document.createElement('span');name.textContent=label;const bar=document.createElement('div');bar.className='timing-bar';const fill=document.createElement('i');fill.style.width=Math.max(1,ms/Math.max(current.ms,1)*100)+'%';bar.append(fill);const n=document.createElement('span');n.textContent=ms+' ms';row.append(name,bar,n);c.append(row);});const note=document.createElement('p');note.className='muted';note.textContent='Measured using performance.now(). Wait includes browser dispatch and endpoint processing. DNS/TLS phases are not measured separately. Animation is excluded.';c.append(note);}if(tab==='learn'){const wrap=document.createElement('div');wrap.className='explain';const [title,desc]=explain();const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=desc;wrap.append(h,p);c.append(wrap);}}
$('#copy').onclick=async()=>{if(!current)return;try{await navigator.clipboard.writeText(current.text);$('#copy').textContent='Copied ✓';setTimeout(()=>$('#copy').textContent='Copy response ⧉',1800);}catch{$('#copy').textContent='Clipboard unavailable';}};
const modal=$('#modal');$('.close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close();};
$('#help').onclick=()=>{$('#modalContent').innerHTML='<div class="eyebrow">THE QUICK CUT</div><h2>HTTP, without the mystery.</h2><ol><li>Choose a scene. Each one explores a common HTTP outcome.</li><li>Send the request and follow the animated journey.</li><li>Inspect the JSON, response headers, and measured timing.</li><li>Toggle <b>Break it</b>, send again, then compare your two runs.</li></ol><p>Built-in endpoints use a service worker: actual fetch calls handled on your device, with no remote backend or saved data. The animation explains the journey; it does not show real packets or network topology.</p><p>For external APIs, use Your own story. CORS must allow access from this site. API credentials are sent only to the URL you enter; do not put private keys in a public demo.</p>';modal.showModal();};
$('#compare').onclick=()=>{const content=$('#modalContent');content.innerHTML='<div class="eyebrow">A DOUBLE FEATURE</div><h2>Two takes. What changed?</h2>';if(history.length<2){const p=document.createElement('p');p.textContent='Send at least two requests. Try the happy path, then enable Break it and send again.';content.append(p);}else{const grid=document.createElement('div');grid.className='comparison';history.slice(-2).forEach((r,i)=>{const a=document.createElement('article');const h=document.createElement('h3');h.textContent=`Take ${history.length-1+i} · ${r.status||'Network error'}`;const p=document.createElement('p');p.textContent=`${r.method} ${r.url} · ${r.ms} ms`;const pre=document.createElement('pre');pre.textContent=JSON.stringify(r.data,null,2);a.append(h,p,pre);grid.append(a);});content.append(grid);}modal.showModal();};
render();
